実装方針: 標準入力からデータを読み込み、与えられたPython関数と同じロジックでsparkline文字列を生成し、標準出力に書き出します。

```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let lines = [];
rl.on('line', (line) => {
    lines.push(line);
});

rl.on('close', () => {
    // 入力解析
    let idx = 0;
    const n = parseInt(lines[idx++]);
    const data = lines[idx++].trim().split(/\s+/).map(Number);
    const min_val = lines[idx] !== '' ? parseFloat(lines[idx]) : null;
    idx++;
    const max_val = lines[idx] !== '' ? parseFloat(lines[idx]) : null;
    idx++;
    const width = parseInt(lines[idx]);

    // sparkline関数
    function sparkline(data, min_val = null, max_val = null, width = 40) {
        if (!data || data.length < 2) {
            return '▁'.repeat(width || 20);
        }
        const n = data.length;
        if (min_val === null) min_val = Math.min(...data);
        if (max_val === null) max_val = Math.max(...data);
        let span = max_val - min_val;
        if (span === 0) span = 1;
        const blocks = ['▁', '▂', '▃', '▄', '▅', '▆', '▇', '█'];
        let result = '';
        for (let i = 0; i < n; i++) {
            let idx = Math.floor((data[i] - min_val) / span * 7.999);
            idx = Math.max(0, Math.min(7, idx));
            result += blocks[idx];
        }
        return result;
    }

    const output = sparkline(data, min_val, max_val, width);
    console.log(output);
});
```

実装方針: 入力からリストを読み取り、各要素を数値に変換してYoY成長率を計算し、結果を指定された形式で出力します。

```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let lines = [];
rl.on('line', (line) => {
    lines.push(line);
});

rl.on('close', () => {
    // 入力解析
    const n = parseInt(lines[0]);
    const values = lines[1].split(' ').map(Number);

    // YoY成長率計算
    const growth = new Array(n).fill(null);
    for (let i = 4; i < n; i++) {
        const prior = values[i - 4];
        if (prior && prior !== 0) {
            growth[i] = (values[i] - prior) / Math.abs(prior) * 100;
        }
    }

    // 出力形式に変換
    const outputLines = [String(n)];
    const formatted = growth.map(v => {
        if (v === null) return '';
        return String(v);
    });
    outputLines.push(formatted.join(' '));

    console.log(outputLines.join('\n'));
});
```

