const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let inputLines = [];
rl.on('line', (line) => {
    inputLines.push(line);
});

rl.on('close', () => {
    // 入力解析
    let idx = 0;
    const numDevices = parseInt(inputLines[idx++]);
    const devices = inputLines[idx++].split(' ').map(x => x === '' ? '' : x);
    const groupSize = parseInt(inputLines[idx++]);

    // グループ化処理
    function groupDeviceNames(devices, group_size) {
        const num_devices = devices.length;
        if (group_size > num_devices) {
            throw new Error(`only ${num_devices} devices, but group_size=${group_size}`);
        }
        const num_groups = Math.floor(num_devices / group_size) + (num_devices % group_size !== 0 ? 1 : 0);
        const groups = Array.from({length: num_groups}, () => []);
        for (let i = 0; i < num_groups * group_size; i++) {
            groups[i % num_groups].push(devices[i % num_devices]);
        }
        return groups;
    }

    const result = groupDeviceNames(devices, groupSize);

    // 出力形式: リストは1行目に要素数、2行目に要素を空白区切り
    // ここではリストのリストなので、外側のリストの要素数、次に各内側リストをPythonのリスト表記で出力
    console.log(result.length);
    console.log(result.map(group => '[' + group.join(' ') + ']').join(' '));
});
