```typescript
function _nfloat(string: string | null): number | string {
    let result: number | string = 0;
    if (string) {
        try {
            result = parseFloat(string);
            if (isNaN(result)) {
                throw new Error("NaN");
            }
        } catch (e) {
            const re1 = /"分红\D*(\d*(?:\.\d*)?)\D*"/;
            const re2 = /.*现金(\d*(?:\.\d*)?)\D*/;
            const re3 = /.*折算(\d*(?:\.\d*)?)\D*/;
            const re4 = /"拆分\D*(\d*(?:\.\d*)?)\D*"/;
            const re5 = /\D*分拆(\d*(?:\.\d*)?)\D*/;

            let match: RegExpMatchArray | null;
            if ((match = string.match(re1))) {
                result = parseFloat(match[1]);
            } else if ((match = string.match(re2))) {
                result = parseFloat(match[1]);
            } else if ((match = string.match(re3))) {
                result = -parseFloat(match[1]);
            } else if ((match = string.match(re4))) {
                result = -parseFloat(match[1]);
            } else if ((match = string.match(re5))) {
                result = -parseFloat(match[1]);
            } else {
                // logger.warning equivalent - just keep original string
                result = string;
            }
        }
    }
    return result;
}

// 標準入力から読み取り
