import * as fs from 'fs';

function indexHostEntities(path: string): Record<string, { calls: number; total_us: number; cat_counts: Record<string, number> }> {
    const idx: Record<string, { calls: number; total_us: number; cat_counts: Record<string, number> }> = {};
    try {
        const data = JSON.parse(fs.readFileSync(path, 'utf-8'));
        const events = Array.isArray(data) ? data : (data.traceEvents || []);
        const host = new Set(['cpu_op', 'user_annotation', 'cuda_runtime', 'hip_runtime']);
        for (const e of events) {
            if (typeof e !== 'object' || e === null) continue;
            const cat = (e as any).cat;
            if (!host.has(cat)) continue;
            const name = (e as any).name || '?';
            if (!idx[name]) {
                idx[name] = { calls: 0, total_us: 0.0, cat_counts: {} };
            }
            idx[name].calls += 1;
            idx[name].total_us += parseFloat((e as any).dur || 0);
            idx[name].cat_counts[cat] = (idx[name].cat_counts[cat] || 0) + 1;
        }
    } catch {
        // ignore errors, return empty idx
    }
    return idx;
}

function formatValue(value: any): string {
    if (value === null || value === undefined) return '';
    if (typeof value === 'boolean') return value ? 'true' : 'false';
    if (typeof value === 'number' || typeof value === 'string') return String(value);
    if (Array.isArray(value)) {
        const lines = [String(value.length)];
        lines.push(value.map(v => formatValue(v)).join(' '));
        return lines.join('\n');
    }
    if (typeof value === 'object') {
        // Python風の辞書表記
        const entries = Object.entries(value).map(([k, v]) => {
            const keyStr = /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(k) ? k : `'${k}'`;
            const valStr = formatValue(v);
            return `${keyStr}: ${valStr}`;
        });
        return `{${entries.join(', ')}}`;
    }
    return String(value);
}

