import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double lambda = Double.parseDouble(sc.nextLine());
        int k = Integer.parseInt(sc.nextLine());
        sc.close();

        double result = calculatePoissonProbability(lambda, k);
        System.out.println(result);
    }

    public static double calculatePoissonProbability(double lambda, int k) {
        // ポアソン分布の確率を計算: (lambda^k * exp(-lambda)) / k!
        double numerator = Math.pow(lambda, k) * Math.exp(-lambda);
        double denominator = factorial(k);
        return numerator / denominator;
    }

    private static double factorial(int n) {
        double result = 1.0;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }
}
