```java
import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        // 最初の引数: value
        String line1 = br.readLine();
        Object value = parseValue(line1, br);
        // 2番目の引数: singleY (省略可能)
        String line2 = br.readLine();
        Object singleY = null;
        if (line2 != null && !line2.isEmpty()) {
            singleY = parseValue(line2, br);
        }
        Object result = asPair(value, singleY);
        printValue(result);
    }

    static Object parseValue(String line, BufferedReader br) throws IOException {
        if (line.equals("true")) return true;
        if (line.equals("false")) return false;
        if (line.isEmpty()) return null;
        // リスト判定: 要素数が1行目、2行目に要素
        try {
            int n = Integer.parseInt(line);
            String[] parts = br.readLine().split(" ");
            List<Object> list = new ArrayList<>();
            for (String p : parts) {
                list.add(parseScalar(p));
            }
            return list;
        } catch (NumberFormatException e) {
            // 数値または文字列
            try {
                if (line.contains(".")) return Double.parseDouble(line);
                return Integer.parseInt(line);
            } catch (NumberFormatException e2) {
                return line; // 文字列
            }
        }
    }

    static Object parseScalar(String s) {
        if (s.equals("true")) return true;
        if (s.equals("false")) return false;
        if (s.equals("None") || s.isEmpty()) return null;
        try {
            if (s.contains(".")) return Double.parseDouble(s);
            return Integer.parseInt(s);
        } catch (NumberFormatException e) {
            return s;
        }
    }

    static Object asPair(Object value, Object singleY) {
        if (value instanceof Integer || value instanceof Double) {
            if (singleY == null) {
                return Arrays.asList(value, value);
            } else {
                return Arrays.asList(value, singleY);
            }
        }
        if (value instanceof List) {
            List<?> list = (List<?>) value;
            if (list.size() == 2) {
                return Arrays.asList(list.get(0), list.get(1));
            }
        }
        throw new IllegalArgumentException(value.toString());
    }

    static void printValue(Object obj) {
        if (obj instanceof List) {
            List<?> list = (List<?>) obj;
            System.out.println(list.size());
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < list.size(); i++) {
                if (i > 0) sb.append(" ");
                sb.append(formatScalar(list.get(i)));
            }
            System.out.println(sb.toString());
        } else {
            System.out.println(formatScalar(obj));
        }
    }

    static String formatScalar(Object obj) {
        if (obj == null) return "";
        if (obj instanceof Boolean) return obj.toString();
        if (obj instanceof Integer || obj instanceof Double) return obj.toString();
        return obj.toString();
    }
}
