```java
import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int numClasses = Integer.parseInt(br.readLine().trim());

        List<List<Integer>> colorMap = getColorMapList(numClasses);

        // 出力
        StringBuilder sb = new StringBuilder();
        sb.append(numClasses).append("\n");
        for (int i = 0; i < colorMap.size(); i++) {
            if (i > 0) sb.append(" ");
            sb.append("[");
            List<Integer> triplet = colorMap.get(i);
            for (int j = 0; j < triplet.size(); j++) {
                if (j > 0) sb.append(", ");
                sb.append(triplet.get(j));
            }
            sb.append("]");
        }
        System.out.println(sb.toString());
    }

    public static List<List<Integer>> getColorMapList(int numClasses) {
        int[] colorMap = new int[numClasses * 3];
        for (int i = 0; i < numClasses; i++) {
            int j = 0;
            int lab = i;
            while (lab != 0) {
                colorMap[i * 3] |= ((lab >> 0) & 1) << (7 - j);
                colorMap[i * 3 + 1] |= ((lab >> 1) & 1) << (7 - j);
                colorMap[i * 3 + 2] |= ((lab >> 2) & 1) << (7 - j);
                j++;
                lab >>= 3;
            }
        }

        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < numClasses; i++) {
            List<Integer> triplet = new ArrayList<>();
            triplet.add(colorMap[i * 3]);
            triplet.add(colorMap[i * 3 + 1]);
            triplet.add(colorMap[i * 3 + 2]);
            result.add(triplet);
        }
        return result;
    }
}
