説明文: 標準入力からJSONファイルパスを読み、ファイルを開いてJSONをパースし、指定されたロジックでエッジ情報を構築して、結果をPythonの辞書形式で出力するC++プログラムを実装します。

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <cctype>
#include <cmath>

// 簡易JSONパーサー（必要な部分のみ）
class JsonValue {
public:
    enum Type { Null, Bool, Number, String, Array, Object };
    Type type;
    bool bool_val;
    double num_val;
    std::string str_val;
    std::vector<JsonValue> array;
    std::vector<std::pair<std::string, JsonValue>> object;

    JsonValue() : type(Null), bool_val(false), num_val(0) {}
};

class JsonParser {
    std::string input;
    size_t pos;
public:
    JsonParser(const std::string& s) : input(s), pos(0) {}

    JsonValue parse() {
        skipWhitespace();
        return parseValue();
    }

private:
    void skipWhitespace() {
        while (pos < input.size() && isspace(input[pos])) pos++;
    }

    JsonValue parseValue() {
        if (pos >= input.size()) return JsonValue();
        char c = input[pos];
        if (c == '{') return parseObject();
        if (c == '[') return parseArray();
        if (c == '"') return parseString();
        if (c == 't' || c == 'f') return parseBool();
        if (c == 'n') { pos += 4; return JsonValue(); }
        return parseNumber();
    }

    JsonValue parseObject() {
        JsonValue obj;
        obj.type = JsonValue::Object;
        pos++; // skip '{'
        skipWhitespace();
        if (pos < input.size() && input[pos] == '}') { pos++; return obj; }
        while (pos < input.size()) {
            skipWhitespace();
            if (input[pos] != '"') break;
            JsonValue key = parseString();
            skipWhitespace();
            if (pos < input.size() && input[pos] == ':') pos++;
            skipWhitespace();
            JsonValue val = parseValue();
            obj.object.push_back({key.str_val, val});
            skipWhitespace();
            if (pos < input.size() && input[pos] == ',') { pos++; continue; }
            if (pos < input.size() && input[pos] == '}') { pos++; break; }
        }
        return obj;
    }

    JsonValue parseArray() {
        JsonValue arr;
        arr.type = JsonValue::Array;
        pos++; // skip '['
        skipWhitespace();
        if (pos < input.size() && input[pos] == ']') { pos++; return arr; }
        while (pos < input.size()) {
            skipWhitespace();
            arr.array.push_back(parseValue());
            skipWhitespace();
            if (pos < input.size() && input[pos] == ',') { pos++; continue; }
            if (pos < input.size() && input[pos] == ']') { pos++; break; }
        }
        return arr;
    }

    JsonValue parseString() {
        JsonValue str;
        str.type = JsonValue::String;
        pos++; // skip '"'
        std::string result;
        while (pos < input.size() && input[pos] != '"') {
            if (input[pos] == '\\') {
                pos++;
                if (pos < input.size()) {
                    char c = input[pos];
                    switch (c) {
                        case 'n': result += '\n'; break;
                        case 't': result += '\t'; break;
                        case 'r': result += '\r'; break;
                        case '\\': result += '\\'; break;
                        case '"': result += '"'; break;
                        default: result += c;
                    }
                    pos++;
                }
            } else {
                result += input[pos++];
            }
        }
        if (pos < input.size()) pos++; // skip closing '"'
        str.str_val = result;
        return str;
    }

    JsonValue parseBool() {
        JsonValue b;
        b.type = JsonValue::Bool;
        if (input.compare(pos, 4, "true") == 0) {
            b.bool_val = true;
            pos += 4;
        } else {
            b.bool_val = false;
            pos += 5;
        }
        return b;
    }

    JsonValue parseNumber() {
        JsonValue num;
        num.type = JsonValue::Number;
        size_t start = pos;
        while (pos < input.size() && (isdigit(input[pos]) || input[pos] == '-' || input[pos] == '+' || input[pos] == '.' || input[pos] == 'e' || input[pos] == 'E')) pos++;
        num.num_val = std::stod(input.substr(start, pos - start));
        return num;
    }
};

// ヘルパー関数
std::string getString(const JsonValue& obj, const std::string& key) {
    if (obj.type != JsonValue::Object) return "";
    for (const auto& p : obj.object) {
        if (p.first == key && p.second.type == JsonValue::String) return p.second.str_val;
    }
    return "";
}

double getNumber(const JsonValue& obj, const std::string& key) {
    if (obj.type != JsonValue::Object) return 0;
    for (const auto& p : obj.object) {
        if (p.first == key && p.second.type == JsonValue::Number) return p.second.num_val;
    }
    return 0;
}

JsonValue getValue(const JsonValue& obj, const std::string& key) {
    if (obj.type != JsonValue::Object) return JsonValue();
    for (const auto& p : obj.object) {
        if (p.first == key) return p.second;
    }
    return JsonValue();
}

bool hasKey(const JsonValue& obj, const std::string& key) {
    if (obj.type != JsonValue::Object) return false;
    for (const auto& p : obj.object) {
        if (p.first == key) return true;
    }
    return false;
}

// 出力用の関数
void printJsonValue(const JsonValue& v) {
    switch (v.type) {
        case JsonValue::Null: std::cout << "None"; break;
        case JsonValue::Bool: std::cout << (v.bool_val ? "True" : "False"); break;
        case JsonValue::Number: {
            double d = v.num_val;
            if (d == floor(d) && fabs(d) < 1e15) {
                std::cout << (long long)d;
            } else {
                std::cout << d;
            }
            break;
        }
        case JsonValue::String: std::cout << "'" << v.str_val << "'"; break;
        case JsonValue::Array: {
            std::cout << "[";
            for (size_t i = 0; i < v.array.size(); i++) {
                if (i > 0) std::cout << ", ";
                printJsonValue(v.array[i]);
            }
            std::cout << "]";
            break;
        }
        case JsonValue::Object: {
            std::cout << "{";
            bool first = true;
            for (const auto& p : v.object) {
                if (!first) std::cout << ", ";
                first = false;
                std::cout << "'" << p.first << "': ";
                printJsonValue(p.second);
            }
            std::cout << "}";
            break;
        }
    }
}

// メイン処理
int main() {
    std::string path;
    std::getline(std::cin, path);

    std::ifstream file(path);
    if (!file.is_open()) {
        std::cout << "{}" << std::endl;
        return 0;
    }
    std::stringstream buffer;
    buffer << file.rdbuf();
    std::string json_str = buffer.str();

    JsonParser parser(json_str);
