        return 0;
    }

    // traceEvents を取得
    std::vector<JsonValue> events;
    if (data.type == JsonValue::Array) {
        events = data.array;
    } else if (data.type == JsonValue::Object && hasKey(data, "traceEvents")) {
        JsonValue te = getValue(data, "traceEvents");
        if (te.type == JsonValue::Array) events = te.array;
    }

    // host_by_ext: map<ext, set<name>>
    std::map<std::string, std::set<std::string>> host_by_ext;
    // spans_by_thread: map<(pid,tid), vector<(start,end,name,ext)>>
    std::map<std::pair<long long, long long>, std::vector<std::tuple<double, double, std::string, std::string>>> spans_by_thread;

    for (const auto& event : events) {
        if (event.type != JsonValue::Object) continue;
        std::string cat = getString(event, "cat");
        if (cat != "cpu_op" && cat != "user_annotation") continue;

        JsonValue args = getValue(event, "args");
        std::string ext;
        if (args.type == JsonValue::Object && hasKey(args, "External id")) {
            JsonValue ext_val = getValue(args, "External id");
            if (ext_val.type == JsonValue::String) ext = ext_val.str_val;
            else if (ext_val.type == JsonValue::Number) {
                double d = ext_val.num_val;
                if (d == floor(d)) ext = std::to_string((long long)d);
                else ext = std::to_string(d);
            }
        }

        if (!ext.empty()) {
            std::string name = getString(event, "name");
            if (name.empty()) name = "?";
            host_by_ext[ext].insert(name);
        }

        if (!ext.empty() && hasKey(event, "ts")) {
            double start = getNumber(event, "ts");
            double dur = getNumber(event, "dur");
            double end = start + dur;
            long long pid = (long long)getNumber(event, "pid");
            long long tid = (long long)getNumber(event, "tid");
            std::string name = getString(event, "name");
            if (name.empty()) name = "?";
            spans_by_thread[{pid, tid}].push_back({start, end, name, ext});
        }
    }

    // スパン処理
    for (auto& kv : spans_by_thread) {
        auto& spans = kv.second;
        std::sort(spans.begin(), spans.end(), [](const auto& a, const auto& b) {
            if (std::get<0>(a) != std::get<0>(b)) return std::get<0>(a) < std::get<0>(b);
            return std::get<1>(a) > std::get<1>(b);
        });

        std::vector<std::pair<double, std::string>> stack;
        for (const auto& span : spans) {
            double start = std::get<0>(span);
            double end = std::get<1>(span);
            std::string name = std::get<2>(span);
            std::string ext = std::get<3>(span);

            while (!stack.empty() && stack.back().first <= start) {
                stack.pop_back();
            }

            auto& names = host_by_ext[ext];
            names.insert(name);
            for (const auto& p : stack) {
                names.insert(p.second);
            }
            stack.push_back({end, name});
        }
    }

    // エッジ構築
    std::map<std::string, std::map<std::string, std::pair<int, double>>> edges;

    for (const auto& event : events) {
        if (event.type != JsonValue::Object) continue;
        std::string cat = getString(event, "cat");
