```cpp
#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <map>
#include <variant>
#include <optional>
#include <memory>

using Json = std::variant<std::nullptr_t, bool, int, double, std::string, std::vector<Json>, std::map<std::string, Json>>;

// パース用の再帰下降パーサー
class Parser {
    std::string s;
    size_t pos = 0;
public:
    Parser(const std::string& str) : s(str) {}

    Json parse() {
        skip_ws();
        Json val = parse_value();
        return val;
    }

private:
    void skip_ws() {
        while (pos < s.size() && (s[pos] == ' ' || s[pos] == '\t' || s[pos] == '\n' || s[pos] == '\r')) pos++;
    }

    Json parse_value() {
        skip_ws();
        if (pos >= s.size()) return nullptr;
        char c = s[pos];
        if (c == '{') return parse_object();
        if (c == '[') return parse_array();
        if (c == '"') return parse_string();
        if (c == 't') { pos += 4; return true; }
        if (c == 'f') { pos += 5; return false; }
        if (c == 'n') { pos += 4; return nullptr; }
        // 数値
        size_t start = pos;
        while (pos < s.size() && (isdigit(s[pos]) || s[pos] == '-' || s[pos] == '.' || s[pos] == 'e' || s[pos] == 'E' || s[pos] == '+' || s[pos] == 'x' || s[pos] == 'a' || s[pos] == 'b' || s[pos] == 'c' || s[pos] == 'd' || s[pos] == 'f')) pos++;
        std::string num = s.substr(start, pos - start);
        // 整数か小数か判定
        if (num.find('.') != std::string::npos || num.find('e') != std::string::npos || num.find('E') != std::string::npos) {
            return std::stod(num);
        } else {
            return std::stoi(num);
        }
    }

    Json parse_object() {
        pos++; // '{'
        std::map<std::string, Json> obj;
        skip_ws();
        if (pos < s.size() && s[pos] == '}') { pos++; return obj; }
        while (true) {
            skip_ws();
            // キー
            if (s[pos] == '"') {
                std::string key = parse_string();
                skip_ws();
                if (s[pos] == ':') pos++;
                Json val = parse_value();
                obj[key] = val;
                skip_ws();
                if (pos < s.size() && s[pos] == ',') { pos++; continue; }
                if (pos < s.size() && s[pos] == '}') { pos++; break; }
            } else {
                // キーが引用符なしの場合（Pythonの辞書表記では通常引用符ありだが、ここでは対応）
                size_t start = pos;
                while (pos < s.size() && s[pos] != ':' && s[pos] != ',' && s[pos] != '}') pos++;
                std::string key = s.substr(start, pos - start);
                // 前後の空白除去
                size_t b = key.find_first_not_of(" \t");
                size_t e = key.find_last_not_of(" \t");
                if (b != std::string::npos) key = key.substr(b, e - b + 1);
                skip_ws();
                if (s[pos] == ':') pos++;
                Json val = parse_value();
                obj[key] = val;
                skip_ws();
                if (pos < s.size() && s[pos] == ',') { pos++; continue; }
                if (pos < s.size() && s[pos] == '}') { pos++; break; }
            }
        }
        return obj;
    }

    Json parse_array() {
        pos++; // '['
        std::vector<Json> arr;
        skip_ws();
        if (pos < s.size() && s[pos] == ']') { pos++; return arr; }
        while (true) {
            Json val = parse_value();
            arr.push_back(val);
            skip_ws();
            if (pos < s.size() && s[pos] == ',') { pos++; continue; }
            if (pos < s.size() && s[pos] == ']') { pos++; break; }
        }
        return arr;
    }

    std::string parse_string() {
        pos++; // '"'
        std::string result;
        while (pos < s.size() && s[pos] != '"') {
            if (s[pos] == '\\' && pos + 1 < s.size()) {
                pos++;
                if (s[pos] == 'n') result += '\n';
                else if (s[pos] == 't') result += '\t';
                else if (s[pos] == '\\') result += '\\';
                else if (s[pos] == '"') result += '"';
                else result += s[pos];
            } else {
                result += s[pos];
            }
            pos++;
        }
        pos++; // closing '"'
        return result;
    }
};

// 出力用関数
void print_json(const Json& val) {
    if (std::holds_alternative<std::nullptr_t>(val)) {
        std::cout << "";
    } else if (std::holds_alternative<bool>(val)) {
        std::cout << (std::get<bool>(val) ? "true" : "false");
    } else if (std::holds_alternative<int>(val)) {
        std::cout << std::get<int>(val);
    } else if (std::holds_alternative<double>(val)) {
        std::cout << std::get<double>(val);
    } else if (std::holds_alternative<std::string>(val)) {
        std::cout << std::get<std::string>(val);
    } else if (std::holds_alternative<std::vector<Json>>(val)) {
        const auto& arr = std::get<std::vector<Json>>(val);
        std::cout << arr.size() << "\n";
        for (size_t i = 0; i < arr.size(); i++) {
