```cpp
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <sstream>
#include <memory>
#include <algorithm>

using namespace std;

// データ構造を表す抽象クラス
struct Node {
    virtual ~Node() = default;
    virtual void print() const = 0;
};

// 整数値
struct IntNode : Node {
    int value;
    IntNode(int v) : value(v) {}
    void print() const override {
        cout << value;
    }
};

// 真偽値
struct BoolNode : Node {
    bool value;
    BoolNode(bool v) : value(v) {}
    void print() const override {
        cout << (value ? "true" : "false");
    }
};

// 文字列
struct StringNode : Node {
    string value;
    StringNode(const string& v) : value(v) {}
    void print() const override {
        cout << value;
    }
};

// None (空)
struct NoneNode : Node {
    void print() const override {
        // 空文字
    }
};

// リスト
struct ListNode : Node {
    vector<shared_ptr<Node>> elements;
    void print() const override {
        cout << elements.size() << "\n";
        for (size_t i = 0; i < elements.size(); ++i) {
            if (i > 0) cout << " ";
            elements[i]->print();
        }
    }
};

// 辞書
struct DictNode : Node {
    vector<pair<string, shared_ptr<Node>>> entries;
    void print() const override {
        // 辞書はPython表記で出力
        cout << "{";
        for (size_t i = 0; i < entries.size(); ++i) {
            if (i > 0) cout << ", ";
            cout << "'" << entries[i].first << "': ";
            entries[i].second->print();
        }
        cout << "}";
    }
};

// 再帰的にデータを読み込む
shared_ptr<Node> readNode() {
    string line;
    if (!getline(cin, line)) return nullptr;
    if (line.empty()) {
        // None
        return make_shared<NoneNode>();
    }
    if (line == "true" || line == "false") {
        return make_shared<BoolNode>(line == "true");
    }
    // 数値かどうか
    bool isNumber = true;
    for (char c : line) {
        if (!isdigit(c) && c != '-') {
            isNumber = false;
            break;
        }
    }
    if (isNumber) {
        return make_shared<IntNode>(stoi(line));
    }
    // リストの場合: 1行目が要素数
    if (line.find_first_not_of("0123456789") == string::npos && !line.empty()) {
        int n = stoi(line);
        auto listNode = make_shared<ListNode>();
        // 次の行に要素が空白区切りで並ぶ
        string elemLine;
        if (getline(cin, elemLine)) {
            stringstream ss(elemLine);
            string token;
            while (ss >> token) {
                // 各要素を再帰的に読む（今回は単純に文字列として扱う）
                if (token == "true" || token == "false") {
                    listNode->elements.push_back(make_shared<BoolNode>(token == "true"));
                } else if (token.empty()) {
                    listNode->elements.push_back(make_shared<NoneNode>());
                } else {
                    // 数値か文字列か
                    bool isNum = true;
                    for (char c : token) {
                        if (!isdigit(c) && c != '-') {
                            isNum = false;
                            break;
                        }
                    }
                    if (isNum) {
                        listNode->elements.push_back(make_shared<IntNode>(stoi(token)));
                    } else {
                        // 文字列（引用符を除去）
                        string clean = token;
                        if (clean.size() >= 2 && clean.front() == '\'' && clean.back() == '\'') {
                            clean = clean.substr(1, clean.size() - 2);
                        }
                        listNode->elements.push_back(make_shared<StringNode>(clean));
                    }
                }
            }
        }
        return listNode;
    }
    // 辞書の場合: Python表記で与えられる
    if (line.front() == '{') {
        auto dictNode = make_shared<DictNode>();
        // 簡易パース: キーと値を分割
        string content = line.substr(1, line.size() - 2);
        stringstream ss(content);
        string pair;
        while (getline(ss, pair, ',')) {
            // キーと値を分割
            size_t colon = pair.find(':');
            if (colon != string::npos) {
                string key = pair.substr(0, colon);
                string val = pair.substr(colon + 1);
                // キーの引用符除去
                key.erase(remove(key.begin(), key.end(), ' '), key.end());
                if (key.size() >= 2 && key.front() == '\'' && key.back() == '\'') {
                    key = key.substr(1, key.size() - 2);
                }
                // 値のパース
                val.erase(remove(val.begin(), val.end(), ' '), val.end());
                shared_ptr<Node> valueNode;
                if (val == "true" || val == "false") {
                    valueNode = make_shared<BoolNode>(val == "true");
                } else if (val.empty()) {
                    valueNode = make_shared<NoneNode>();
                } else {
                    bool isNum = true;
                    for (char c : val) {
                        if (!isdigit(c) && c != '-') {
                            isNum = false;
                            break;
                        }
                    }
                    if (isNum) {
                        valueNode = make_shared<IntNode>(stoi(val));
                    } else {
                        if (val.size() >= 2 && val.front() == '\'' && val.back() == '\'') {
                            val = val.substr(1, val.size() - 2);
                        }
                        valueNode = make_shared<StringNode>(val);
                    }
                }
                dictNode->entries.push_back({key, valueNode});
            }
        }
        return dictNode;
    }
    // 文字列
    return make_shared<StringNode>(line);
}

int main() {
    // 入力全体を読み込む
    string allInput;
    string line;
    while (getline(cin, line)) {
        allInput += line + "\n";
    }
    // 入力を再解析するためにstringstreamに戻す
    stringstream ss(allInput);
    cin.rdbuf(ss.rdbuf());

    // 最初の行を読む
    shared_ptr<Node> root = readNode();
    if (root) {
        root->print();
        cout << "\n";
    }
    return 0;
}
