using namespace std;

// 定数定義
const uint32_t RT_PRESENT_TSFT = 0x00000001;
const uint32_t RT_PRESENT_FLAGS = 0x00000002;
const uint32_t RT_PRESENT_RATE = 0x00000004;
const uint32_t RT_PRESENT_CHANNEL = 0x00000008;
const uint32_t RT_PRESENT_FHSS = 0x00000010;
const uint32_t RT_PRESENT_DBM_ANTSIGNAL = 0x00000020;
const uint32_t RT_PRESENT_DBM_ANTNOISE = 0x00000040;
const uint32_t RT_PRESENT_LOCK_QUALITY = 0x00000080;
const uint32_t RT_PRESENT_TX_ATTENUATION = 0x00000100;
const uint32_t RT_PRESENT_DB_TX_ATTENUATION = 0x00000200;
const uint32_t RT_PRESENT_DBM_TX_POWER = 0x00000400;
const uint32_t RT_PRESENT_ANTENNA = 0x00000800;

int frequency_to_channel(int freq) {
    if (freq >= 2412 && freq <= 2484) return (freq - 2407) / 5;
    if (freq >= 5180 && freq <= 5825) return (freq - 5000) / 5;
    return 0;
}

string bool_to_string(bool b) {
    return b ? "true" : "false";
}

string int_to_string(int v) {
    return to_string(v);
}

string double_to_string(double v) {
    ostringstream oss;
    oss << v;
    return oss.str();
}

string dict_to_string(const map<string, string>& dict) {
    string result = "{";
    bool first = true;
    for (const auto& kv : dict) {
        if (!first) result += ", ";
        result += "'" + kv.first + "': " + kv.second;
        first = false;
    }
    result += "}";
    return result;
}

int main() {
    // バイト列を読み込む（バイナリとして）
    vector<uint8_t> packet_data;
    string line;
    while (getline(cin, line)) {
        if (line.empty()) break;
        // 各行をバイトとして解釈（16進数でなく、そのままの文字コード）
        for (char c : line) {
            packet_data.push_back(static_cast<uint8_t>(c));
        }
        packet_data.push_back('\n'); // 改行も含める
    }
    // 最後の改行を削除
    if (!packet_data.empty() && packet_data.back() == '\n') {
        packet_data.pop_back();
    }

    // 結果の初期化
    map<string, string> result;
    result["rssi"] = "-99";
    result["noise"] = "None";
    result["frequency"] = "0";
    result["channel"] = "0";
    result["flags"] = "0";
    result["rate"] = "0";
    result["antenna"] = "0";
    result["fcs_present"] = "false";
    result["header_len"] = "0";

    if (packet_data.size() < 8) {
        cout << dict_to_string(result) << endl;
        return 0;
    }

    // バージョン、パッド、ヘッダー長を読み取る（リトルエンディアン）
    uint8_t version = packet_data[0];
    uint8_t pad = packet_data[1];
    uint16_t header_len = packet_data[2] | (packet_data[3] << 8);
    result["header_len"] = int_to_string(header_len);

    if (header_len > packet_data.size() || header_len < 8) {
        cout << dict_to_string(result) << endl;
        return 0;
    }

    // present flags を読み取る
    vector<uint32_t> present_flags;
    int offset = 4;
    while (offset + 4 <= header_len) {
        uint32_t present = packet_data[offset] | (packet_data[offset+1] << 8) |
                          (packet_data[offset+2] << 16) | (packet_data[offset+3] << 24);
        present_flags.push_back(present);
        offset += 4;
        if (!(present & 0x80000000)) break;
    }

    if (present_flags.empty()) {
        cout << dict_to_string(result) << endl;
        return 0;
    }

    uint32_t first_present = present_flags[0];
    int data_offset = 4 + present_flags.size() * 4;

    auto align_to = [](int off, int alignment) -> int {
        int remainder = off % alignment;
        return remainder ? off + (alignment - remainder) : off;
    };

    if (first_present & RT_PRESENT_TSFT) {
        data_offset = align_to(data_offset, 8);
        data_offset += 8;
    }
    if (first_present & RT_PRESENT_FLAGS) {
        if (data_offset < header_len) {
            uint8_t flags = packet_data[data_offset];
            result["flags"] = int_to_string(flags);
            result["fcs_present"] = bool_to_string(flags & 16);
        }
        data_offset += 1;
    }
    if (first_present & RT_PRESENT_RATE) {
        if (data_offset < header_len) {
            double rate = packet_data[data_offset] * 0.5;
            result["rate"] = double_to_string(rate);
        }
        data_offset += 1;
    }
    if (first_present & RT_PRESENT_CHANNEL) {
        data_offset = align_to(data_offset, 2);
        if (data_offset + 4 <= header_len) {
            uint16_t freq = packet_data[data_offset] | (packet_data[data_offset+1] << 8);
            uint16_t chan_flags = packet_data[data_offset+2] | (packet_data[data_offset+3] << 8);
            result["frequency"] = int_to_string(freq);
            result["channel"] = int_to_string(frequency_to_channel(freq));
        }
        data_offset += 4;
    }
    if (first_present & RT_PRESENT_FHSS) {
        data_offset += 2;
    }
    if (first_present & RT_PRESENT_DBM_ANTSIGNAL) {
        if (data_offset < header_len) {
            int8_t rssi = static_cast<int8_t>(packet_data[data_offset]);
            result["rssi"] = int_to_string(rssi);
        }
        data_offset += 1;
    }
    if (first_present & RT_PRESENT_DBM_ANTNOISE) {
        if (data_offset < header_len) {
            int8_t noise = static_cast<int8_t>(packet_data[data_offset]);
            result["noise"] = int_to_string(noise);
        }
        data_offset += 1;
    }
    if (first_present & RT_PRESENT_LOCK_QUALITY) {
        data_offset = align_to(data_offset, 2);
        data_offset += 2;
    }
    if (first_present & RT_PRESENT_TX_ATTENUATION) {
        data_offset = align_to(data_offset, 2);
        data_offset += 2;
    }
    if (first_present & RT_PRESENT_DB_TX_ATTENUATION) {
        data_offset = align_to(data_offset, 2);
        data_offset += 2;
    }
    if (first_present & RT_PRESENT_DBM_TX_POWER) {
        data_offset += 1;
    }
    if (first_present & RT_PRESENT_ANTENNA) {
        if (data_offset < header_len) {
            result["antenna"] = int_to_string(packet_data[data_offset]);
        }
        data_offset += 1;
    }

