実装方針: 標準入力から引数を読み取り、C#のHttpClientと手動のJSON解析でDevice Flowの各ステップを実装し、結果を指定された形式で出力します。

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static void Main()
    {
        string ssoCookie = Console.ReadLine() ?? "";
        string browserApproveStr = Console.ReadLine() ?? "false";
        bool browserApprove = bool.Parse(browserApproveStr);
        string proxy = Console.ReadLine() ?? "";

        var result = SsoToTokenDeviceBrowser(ssoCookie, browserApprove, proxy);
        Console.WriteLine(result ?? "");
    }

    static string SsoToTokenDeviceBrowser(string ssoCookie, bool browserApprove, string proxy)
    {
        ssoCookie = (ssoCookie ?? "").Trim();
        if (string.IsNullOrEmpty(ssoCookie))
        {
            return null;
        }

        // セッション確認
        using (var client = CreateHttpClient(proxy, ssoCookie))
        {
            try
            {
                var response = client.GetAsync("https://accounts.x.ai/").Result;
                string finalUrl = response.RequestMessage.RequestUri.ToString();
                int status = (int)response.StatusCode;
                if (finalUrl.Contains("sign-in") || finalUrl.Contains("sign-up") || status == 401)
                {
                    return null;
                }
            }
            catch
            {
                return null;
            }
        }

        // Device code取得
        var device = RequestDeviceCode(proxy);
        if (device == null) return null;

        string openUrl = device.ContainsKey("open_url") ? device["open_url"] : "";
        if (!string.IsNullOrEmpty(openUrl) && !IsTrustedXaiUrl(openUrl))
        {
            return null;
        }

        // ブラウザ承認
        bool ok = false;
        try
        {
            ok = browserApprove;
        }
        catch
        {
            return null;
        }
        if (!ok) return null;

        // トークン取得
        string deviceCode = device["device_code"];
        int interval = device.ContainsKey("interval") ? int.Parse(device["interval"]) : 5;
        int expiresIn = device.ContainsKey("expires_in") ? int.Parse(device["expires_in"]) : 1800;
        return PollDeviceToken(deviceCode, interval, expiresIn, proxy);
    }

    static HttpClient CreateHttpClient(string proxy, string cookie = null)
    {
        var handler = new HttpClientHandler();
        if (!string.IsNullOrEmpty(proxy))
        {
            handler.Proxy = new System.Net.WebProxy(proxy);
            handler.UseProxy = true;
        }
        var client = new HttpClient(handler);
        client.Timeout = TimeSpan.FromSeconds(15);
        if (!string.IsNullOrEmpty(cookie))
        {
            client.DefaultRequestHeaders.Add("Cookie", cookie);
        }
        client.DefaultRequestHeaders.Add("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36");
        return client;
    }

    static Dictionary<string, string> RequestDeviceCode(string proxy)
    {
        using (var client = CreateHttpClient(proxy))
        {
            var content = new FormUrlEncodedContent(new Dictionary<string, string>
            {
                { "client_id", "xai" },
                { "scope", "openai" }
            });
            var response = client.PostAsync("https://accounts.x.ai/oauth/device/code", content).Result;
            if (!response.IsSuccessStatusCode) return null;
            string json = response.Content.ReadAsStringAsync().Result;
            var doc = JsonDocument.Parse(json);
            var dict = new Dictionary<string, string>();
            foreach (var prop in doc.RootElement.EnumerateObject())
            {
                dict[prop.Name] = prop.Value.ToString();
            }
            return dict;
        }
    }

    static bool IsTrustedXaiUrl(string url)
    {
        return url.StartsWith("https://accounts.x.ai/") || url.StartsWith("https://x.ai/");
    }

    static string PollDeviceToken(string deviceCode, int interval, int expiresIn, string proxy)
    {
        using (var client = CreateHttpClient(proxy))
        {
            var start = DateTime.UtcNow;
            while ((DateTime.UtcNow - start).TotalSeconds < expiresIn)
            {
                var content = new FormUrlEncodedContent(new Dictionary<string, string>
                {
                    { "grant_type", "urn:ietf:params:oauth:grant-type:device_code" },
                    { "device_code", deviceCode },
                    { "client_id", "xai" }
                });
                var response = client.PostAsync("https://accounts.x.ai/oauth/token", content).Result;
                string json = response.Content.ReadAsStringAsync().Result;
                if (response.IsSuccessStatusCode)
                {
                    return json;
                }
                else if (response.StatusCode == System.Net.HttpStatusCode.BadRequest)
                {
                    var doc = JsonDocument.Parse(json);
                    string error = doc.RootElement.GetProperty("error").GetString();
                    if (error == "authorization_pending" || error == "slow_down")
                    {
                        Thread.Sleep(interval * 1000);
                        continue;
                    }
                    else if (error == "access_denied" || error == "expired_token")
                    {
                        return null;
                    }
                    else
                    {
                        return null;
                    }
                }
                else
                {
                    return null;
                }
            }
            return null;
        }
    }
}
