```csharp
using System;
using System.Collections.Generic;
using System.Text.Json;

class Program
{
    static void Main()
    {
        string policyDocStr = Console.ReadLine();
        string routeArn = Console.ReadLine();

        // 空文字はNone扱い
        if (string.IsNullOrEmpty(policyDocStr))
        {
            Console.WriteLine("NoMatch");
            return;
        }

        var policyDoc = ParseDict(policyDocStr);
        string result = EvaluateAuthorizerPolicy(policyDoc, routeArn);
        Console.WriteLine(result);
    }

    static Dictionary<string, object> ParseDict(string s)
    {
        // Pythonの辞書表記をJSONに変換してパース
        string json = s.Replace("'", "\"");
        json = json.Replace("True", "true").Replace("False", "false").Replace("None", "null");
        using var doc = JsonDocument.Parse(json);
        var dict = new Dictionary<string, object>();
        foreach (var prop in doc.RootElement.EnumerateObject())
        {
            dict[prop.Name] = ConvertJsonElement(prop.Value);
        }
        return dict;
    }

    static object ConvertJsonElement(JsonElement el)
    {
        switch (el.ValueKind)
        {
            case JsonValueKind.String:
                return el.GetString();
            case JsonValueKind.Number:
                return el.GetInt64();
            case JsonValueKind.True:
                return true;
            case JsonValueKind.False:
                return false;
            case JsonValueKind.Null:
                return null;
            case JsonValueKind.Array:
                var list = new List<object>();
                foreach (var item in el.EnumerateArray())
                    list.Add(ConvertJsonElement(item));
                return list;
            case JsonValueKind.Object:
                var dict = new Dictionary<string, object>();
                foreach (var prop in el.EnumerateObject())
                    dict[prop.Name] = ConvertJsonElement(prop.Value);
                return dict;
            default:
                return null;
        }
    }

    static string EvaluateAuthorizerPolicy(Dictionary<string, object> policyDoc, string routeArn)
    {
        if (policyDoc == null)
            return "NoMatch";

        object stmtObj;
        if (!policyDoc.TryGetValue("Statement", out stmtObj) || stmtObj == null)
            return "NoMatch";

        List<object> statements;
        if (stmtObj is Dictionary<string, object>)
            statements = new List<object> { stmtObj };
        else if (stmtObj is List<object>)
            statements = (List<object>)stmtObj;
        else
            return "NoMatch";

        bool allow = false;
        foreach (var st in statements)
        {
            if (!(st is Dictionary<string, object> stDict))
                continue;

            object resObj;
            if (!stDict.TryGetValue("Resource", out resObj) || resObj == null)
                continue;

            List<string> resources;
            if (resObj is string)
                resources = new List<string> { (string)resObj };
            else if (resObj is List<object>)
            {
                resources = new List<string>();
                foreach (var r in (List<object>)resObj)
                    if (r is string s) resources.Add(s);
            }
            else
                continue;

            bool matched = false;
            foreach (var r in resources)
            {
                if (AuthorizerArnMatches(r, routeArn))
                {
                    matched = true;
                    break;
                }
            }
            if (!matched) continue;

            object effectObj;
            if (stDict.TryGetValue("Effect", out effectObj) && effectObj is string effect)
            {
                if (effect == "Deny")
                    return "Deny";
                if (effect == "Allow")
                    allow = true;
            }
        }
        return allow ? "Allow" : "NoMatch";
    }

    static bool AuthorizerArnMatches(string pattern, string arn)
    {
        // 単純なワイルドカード * と ? をサポート
        int p = 0, a = 0;
        int starIdx = -1, matchIdx = 0;
        while (a < arn.Length)
        {
            if (p < pattern.Length && (pattern[p] == '?' || pattern[p] == arn[a]))
            {
                p++;
                a++;
            }
            else if (p < pattern.Length && pattern[p] == '*')
            {
                starIdx = p;
                matchIdx = a;
                p++;
            }
            else if (starIdx != -1)
            {
                p = starIdx + 1;
                matchIdx++;
                a = matchIdx;
            }
            else
            {
                return false;
            }
        }
        while (p < pattern.Length && pattern[p] == '*')
            p++;
        return p == pattern.Length;
    }
}
