```go
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"
)

func stableIDKey(nodeID string) string {
	// 辞書形式かどうかを判定（{で始まり}で終わる場合）
	trimmed := strings.TrimSpace(nodeID)
	if strings.HasPrefix(trimmed, "{") && strings.HasSuffix(trimmed, "}") {
		// JSON風の辞書をパース
		var m map[string]interface{}
		if err := json.Unmarshal([]byte(trimmed), &m); err == nil {
			// キーをソートしてJSONに変換
			keys := make([]string, 0, len(m))
			for k := range m {
				keys = append(keys, k)
			}
			sort.Strings(keys)
			var sb strings.Builder
			sb.WriteString("{")
			for i, k := range keys {
				if i > 0 {
					sb.WriteString(",")
				}
				keyJSON, _ := json.Marshal(k)
				valJSON, _ := json.Marshal(m[k])
				sb.Write(keyJSON)
				sb.WriteString(":")
				sb.Write(valJSON)
			}
			sb.WriteString("}")
			return sb.String()
		}
	}
	return nodeID
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	input := scanner.Text()
	result := stableIDKey(input)
	fmt.Println(result)
}
