    let n: usize = lines.next().unwrap().unwrap().trim().parse().unwrap();
    // 2行目: トークン文字列
    let toks_line = lines.next().unwrap().unwrap();
    let toks: Vec<String> = toks_line.split_whitespace().map(String::from).collect();
    // 3行目: 種類文字列
    let kinds_line = lines.next().unwrap().unwrap();
    let kinds: Vec<String> = kinds_line.split_whitespace().map(String::from).collect();
    // 4行目: type_only
    let type_only_line = lines.next().unwrap().unwrap();
    let type_only: bool = type_only_line.trim() == "true";
    // ここではtype_onlyは使わないが、入力として読む
    let _ = type_only;
    (toks, kinds)
}

fn check_type_var_decl(cur_line: (&Vec<String>, &Vec<String>), type_only: bool) -> (Vec<Option<usize>>, Vec<Vec<Option<usize>>>) {
    let toks = cur_line.0;
    let kinds = cur_line.1;
    let line_len = kinds.len();
    let mut inside_type = false;
    let mut type_s: Option<usize> = None;
    let mut type_e: Option<usize> = None;
    let mut var_pos_list: Vec<Vec<Option<usize>>> = Vec::new();

    for j in 0..line_len {
        let kind = kinds[j].as_str();
        if kind == "type" {
            if !inside_type {
                inside_type = true;
                type_s = Some(j);
            }
        } else if inside_type {
            if kind == "name" {
                type_e = Some(j);
            }
            break;
        }
    }

    if type_e.is_none() {
        return (vec![None, None], vec![]);
    }

    if type_only {
        return (vec![type_s, type_e], vec![]);
    }

    let mut var_s: Option<usize> = None;
    let mut var_e: Option<usize> = None;
    let type_e_val = type_e.unwrap();

    for j in type_e_val..line_len {
        let kind = kinds[j].as_str();
        let tok = toks[j].as_str();
        if kind == "name" {
