        } else if tok == ";" {
            var_e = Some(j);
            var_pos_list.push(vec![var_s, var_e]);
            break;
        }
    }

    (vec![type_s, type_e], var_pos_list)
}

fn format_output(result: (Vec<Option<usize>>, Vec<Vec<Option<usize>>>)) -> String {
    let (type_range, var_list) = result;
    // 最初の要素数
    let mut out = String::new();
    // 型範囲の表現: [None, None] または [Some, Some]
    let type_str = format!(
        "[{}, {}]",
        match type_range[0] {
            Some(v) => v.to_string(),
            None => "None".to_string(),
