```rust
use std::collections::HashSet;
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let name = lines.next().unwrap().unwrap();

    let candidates = generate_typosquat_candidates(&name);

    println!("{}", candidates.len());
    println!("{}", candidates.join(" "));
}

fn generate_typosquat_candidates(name: &str) -> Vec<String> {
    let mut candidates = HashSet::new();
    let lower_name = name.to_lowercase();
    let chars: Vec<char> = lower_name.chars().collect();
    let len = chars.len();

    // 文字削除
    for i in 0..len {
        let mut candidate = String::new();
        for (j, c) in chars.iter().enumerate() {
            if j != i {
                candidate.push(*c);
            }
        }
        if !candidate.is_empty() && candidate != lower_name {
            candidates.insert(candidate);
        }
    }

    // 文字入れ替え
    for i in 0..len.saturating_sub(1) {
        let mut new_chars = chars.clone();
        new_chars.swap(i, i + 1);
        let candidate: String = new_chars.into_iter().collect();
        if candidate != lower_name {
            candidates.insert(candidate);
        }
    }

    // 文字挿入（同じ文字を2回）
    for i in 0..len {
        let mut candidate = String::new();
        for (j, c) in chars.iter().enumerate() {
            if j == i {
                candidate.push(*c);
            }
            candidate.push(*c);
        }
        if candidate != lower_name {
            candidates.insert(candidate);
        }
    }

    // キーボード隣接文字への置換
    let qwerty_neighbors: std::collections::HashMap<char, &str> = [
        ('q', "wa"), ('w', "qeas"), ('e', "wrds"), ('r', "etfs"), ('t', "ryg"),
        ('y', "tuh"), ('u', "yij"), ('i', "uok"), ('o', "ipl"), ('p', "ol"),
        ('a', "qwsz"), ('s', "wedxza"), ('d', "erfcxs"), ('f', "rtgvcd"),
        ('g', "tyhbvf"), ('h', "yujng"), ('j', "uikmh"), ('k', "ioljm"),
        ('l', "opk"), ('z', "asx"), ('x', "zsdc"), ('c', "xdfv"),
        ('v', "cfgb"), ('b', "vghn"), ('n', "bhjm"), ('m', "njk")
    ].iter().cloned().collect();

    for i in 0..len {
        let ch = chars[i];
        if let Some(neighbors) = qwerty_neighbors.get(&ch) {
            for neighbor in neighbors.chars() {
                let mut candidate = String::new();
                for (j, c) in chars.iter().enumerate() {
                    if j == i {
                        candidate.push(neighbor);
                    } else {
                        candidate.push(*c);
                    }
                }
                if candidate != lower_name {
                    candidates.insert(candidate);
                }
            }
        }
    }

    // セパレータ操作
    if lower_name.contains('-') || lower_name.contains('_') {
        candidates.insert(lower_name.replace('-', "").replace('_', ""));
        candidates.insert(lower_name.replace('-', "_"));
        candidates.insert(lower_name.replace('_', "-"));
        candidates.insert(lower_name.replace('-', "--"));
    }

    // 接頭辞・接尾辞
    let affixes = ["python-", "py-", "-python", "-py", "-lib", "-sdk", "2", "3"];
    for affix in affixes.iter() {
        if affix.starts_with('-') {
            candidates.insert(format!("{}{}", lower_name, affix));
        } else {
            candidates.insert(format!("{}{}", affix, lower_name));
        }
    }

    candidates.remove(&lower_name);
    candidates.remove(name);

    let mut sorted: Vec<String> = candidates.into_iter().collect();
    sorted.sort();
    sorted
}
