```rust
use std::io::{self, BufRead};

fn token_from_url(url: &str) -> Option<String> {
    let query_params = if let Some(pos) = url.find('?') {
        &url[pos + 1..]
    } else {
        url
    };

    for pair in query_params.split('&') {
        if pair.starts_with("token=") {
            return Some(pair[6..].to_string());
        }
    }
    None
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    if let Some(Ok(url)) = lines.next() {
        let result = token_from_url(&url);
        match result {
            Some(token) => println!("{}", token),
            None => println!(),
        }
    }
}
```

