```rust
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    // 最初の行を読む
    let first_line = lines.next().unwrap().unwrap();

    // 空行ならエラー
    if first_line.is_empty() {
        eprintln!("Error");
        return;
    }

    // 整数かどうか判定
    if let Ok(num) = first_line.parse::<i64>() {
        // 整数の場合
        if num < 0 {
            eprintln!("Error");
            return;
        }
        println!("3");
        println!("{} {} {}", num, num, num);
    } else {
        // リスト形式の場合: 要素数を読む
        let count: usize = first_line.parse().unwrap_or(0);
        if count != 3 {
            eprintln!("Error");
            return;
        }

        // 次の行を読む
        let second_line = lines.next().unwrap().unwrap();
        let parts: Vec<&str> = second_line.split_whitespace().collect();

        if parts.len() != 3 {
            eprintln!("Error");
            return;
        }

        let mut values = Vec::new();
        for part in parts {
            match part.parse::<i64>() {
                Ok(v) if v >= 0 => values.push(v),
                _ => {
                    eprintln!("Error");
                    return;
                }
            }
        }

        println!("3");
        println!("{} {} {}", values[0], values[1], values[2]);
    }
}
```

